import {attachMusic} from './music.mjs';
import {renderMarkup,validateConfig,mergeConfig,calendarText,safeUrl} from './template.mjs';
import {ICON_CATALOG,iconSvg} from './icons.mjs';
let currentConfig=null,cleanup=()=>{},currentRoot=null;
const clone=v=>structuredClone(v);
function download(text,name,type){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
export function mount(config,root=document.querySelector('#invitation-root')){
 const errors=validateConfig(config);if(errors.length)throw new Error('Invalid config: '+errors.join(', '));const markup=renderMarkup(config);if(!root)throw new Error('Missing invitation root');cleanup();if(currentRoot&&currentRoot!==root)currentRoot.replaceChildren();currentRoot=root;currentConfig=clone(config);const c=currentConfig;root.innerHTML=markup;root.classList.toggle('no-opening',!root.querySelector('#opening'));
 const $=s=>root.querySelector(s),$$=s=>root.querySelectorAll(s);const controller=new AbortController();const signal=controller.signal;const on=(el,event,fn,opts={})=>el?.addEventListener(event,fn,{...opts,signal});
 const stopMusic=attachMusic({button:$('#music-toggle'),audio:$('#invitation-audio'),status:$('#music-status'),config:c.music,signal});
 on(window,'pagehide',()=>$('#invitation-audio')?.pause());
 document.documentElement.lang=c.locale;document.title=c.meta.title;document.querySelector('meta[name=description]')?.setAttribute('content',c.meta.description);document.querySelector('meta[name=theme-color]')?.setAttribute('content',c.theme.paper);
 for(const [key,value] of Object.entries(c.theme))root.style.setProperty('--'+key,value);for(const [key,value] of Object.entries(c.assets))root.style.setProperty('--asset-'+key,`url("${safeUrl(value).replace(/"/g,'%22')}")`);
 document.body.style.backgroundColor=c.theme.paper;
 // A failed photo gets a bounded placeholder; no broken-image glyph or lost frame.
 $$('.couple-photo').forEach(img=>{const fail=()=>{img.hidden=true;const p=img.parentElement.querySelector('.photo-placeholder');p.hidden=false;p.querySelector('span').textContent=c.ui.photoError};on(img,'error',fail);if(img.complete&&!img.naturalWidth)fail()});
 function tick(){const target=$('#countdown');if(!target)return;const t=Math.max(0,Date.parse(c.event.startAt)-Date.now());const values=[Math.floor(t/86400000),Math.floor(t/3600000)%24,Math.floor(t/60000)%60];target.replaceChildren(...values.map((value,i)=>{const box=document.createElement('div'),b=document.createElement('b'),small=document.createElement('small');b.textContent=String(value).padStart(2,'0');small.textContent=c.day.countdownUnits[i];box.append(b,small);return box}))}tick();const timer=setInterval(tick,60000);
 const motion=matchMedia('(prefers-reduced-motion: reduce)');const clamp=n=>Math.min(1,Math.max(0,n)),phase=(p,a,b)=>clamp((p-a)/(b-a)),ease=t=>t*t*(3-2*t);let frame=0;
 function animate(){frame=0;const progress=$('.reading-progress');if(progress)progress.style.width=100*scrollY/Math.max(1,document.documentElement.scrollHeight-innerHeight)+'%';const opening=$('#opening');if(!opening)return;const disabled=motion.matches||!c.layout.animation;opening.classList.toggle('motion-off',disabled);if(disabled){for(const selector of ['.envelope-stage','.hero-heading','.wax-seal','.envelope-flap','.letter','.scroll-prompt'])$(selector).removeAttribute('style');return}
 const p=clamp((scrollY-opening.offsetTop)/Math.max(1,opening.offsetHeight-innerHeight)),enter=ease(phase(p,0,.17)),seal=ease(phase(p,.19,.32)),flap=ease(phase(p,.32,.59)),rise=ease(phase(p,.63,.91));
 $('.envelope-stage').style.transform=`translateX(-50%) translateY(${-enter*12}px) rotate(${-3*(1-enter)}deg) scale(${.96+enter*.04})`;
 $('.hero-heading').style.opacity=1-ease(phase(p,.18,.4));$('.hero-heading').style.transform=`translateY(${-phase(p,.18,.4)*35}px)`;
 $('.wax-seal').style.transform=`translate(${seal*24}px,${-seal*80}px) rotate(${seal*20}deg) scale(${1+seal*.13})`;$('.wax-seal').style.opacity=1-seal;
 $('.envelope-flap').style.transform=`rotateX(${flap*180}deg)`;$('.envelope-flap').style.zIndex=flap>.5?'0':'6';$('.letter').style.transform=`translateY(${-rise*108}%)`;$('.scroll-prompt').style.opacity=1-phase(p,.03,.15);
 }
 on(window,'scroll',()=>{if(!frame)frame=requestAnimationFrame(animate)},{passive:true});on(window,'resize',animate);on(motion,'change',animate);animate();on($('#open-letter'),'click',()=>{const el=$('#opening');window.scrollTo({top:el.offsetTop+el.offsetHeight-innerHeight,behavior:motion.matches?'instant':'smooth'})});
 let observer=null;if(c.layout.animation&&!motion.matches&&'IntersectionObserver' in window){observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('visible');observer.unobserve(entry.target)}}),{threshold:.1});$$('.reveal').forEach(el=>observer.observe(el))}else $$('.reveal').forEach(el=>el.classList.add('visible'));
 on($('#calendar-download'),'click',()=>download(calendarText(c),c.event.calendarFileName,'text/calendar;charset=utf-8'));
 const form=$('#rsvp-form');let answer=null;const storageKey='ivory:rsvp:'+c.id;const messages=c.rsvp.messages;
 if(form){try{const cached=JSON.parse(localStorage.getItem(storageKey)||'null');if(cached?.answers){answer=cached;for(const field of c.rsvp.fields){const value=cached.answers[field.id];if(typeof value!=='string')continue;const controls=[...form.elements].filter(el=>el.name===field.id);for(const control of controls){if(control.type==='radio')control.checked=control.value===value;else control.value=value}}$('#answer-download').hidden=false}}catch{}
 on(form,'input',event=>event.target.setCustomValidity?.(''));
 on(form,'submit',async event=>{event.preventDefault();const values=Object.fromEntries(new FormData(form));for(const field of c.rsvp.fields){if(typeof values[field.id]==='string')values[field.id]=values[field.id].trim();if(field.required&&!values[field.id]){const control=[...form.elements].find(x=>x.name===field.id);control.setCustomValidity(messages.required);control.reportValidity();return}}
 answer={invitationId:c.id,submittedAt:new Date().toISOString(),answers:values};const status=$('#form-status');
 if(c.rsvp.submission.mode==='local'){try{localStorage.setItem(storageKey,JSON.stringify(answer));status.textContent=messages.localSuccess}catch{status.textContent=messages.storageError}$('#answer-download').hidden=false;root.dispatchEvent(new CustomEvent('invitation:rsvp',{detail:{mode:'local',payload:clone(answer)},bubbles:true}));return}
 const button=form.querySelector('[type=submit]');button.disabled=true;button.textContent=c.rsvp.submittingLabel;status.textContent='';const request=new AbortController();const stop=()=>request.abort();signal.addEventListener('abort',stop,{once:true});const timeout=setTimeout(stop,20000);
 try{const response=await fetch(safeUrl(c.rsvp.submission.endpoint),{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(answer),signal:request.signal,credentials:'omit'});if(!response.ok)throw new Error('RSVP HTTP '+response.status);if(signal.aborted)return;status.textContent=messages.success;root.dispatchEvent(new CustomEvent('invitation:rsvp',{detail:{mode:'endpoint',payload:clone(answer)},bubbles:true}))}catch{if(!signal.aborted)status.textContent=messages.error}finally{clearTimeout(timeout);signal.removeEventListener('abort',stop);if(!signal.aborted){button.disabled=false;button.replaceChildren(document.createTextNode(c.rsvp.submitLabel));button.insertAdjacentHTML('beforeend',iconSvg('arrowRight'));$('#answer-download').hidden=false}}
 });on($('#answer-download'),'click',()=>{if(answer)download(JSON.stringify(answer,null,2),c.rsvp.downloadFileName,'application/json;charset=utf-8')});}
 cleanup=()=>{stopMusic();controller.abort();observer?.disconnect();clearInterval(timer);if(frame)cancelAnimationFrame(frame)};
 root.dispatchEvent(new CustomEvent('invitation:rendered',{detail:{id:c.id},bubbles:true}));return clone(c);
}
export function update(patch){if(!currentConfig)throw new Error('Mount first');return mount(mergeConfig(currentConfig,patch),currentRoot)}
export function destroy(){cleanup();currentRoot?.replaceChildren();currentRoot=null;currentConfig=null}
window.WeddingInvitation=Object.freeze({mount,update,destroy,validate:validateConfig,getConfig:()=>clone(currentConfig),getIconCatalog:()=>clone(ICON_CATALOG)});
try{const config=window.WEDDING_CONFIG??await fetch(new URL('./config.json',import.meta.url),{cache:'no-store'}).then(r=>{if(!r.ok)throw new Error('Config HTTP '+r.status);return r.json()});mount(config)}catch(error){console.error(error);const root=document.querySelector('#invitation-root');root.textContent=window.WEDDING_CONFIG?.ui?.loadError||'Не удалось загрузить приглашение. Проверьте config.json.';root.setAttribute('role','alert')}
